-- Generated from learning/culture-seeds.ts. Do not edit by hand.
-- Regenerate with: pnpm curriculum:generate
--
-- Culture and pragmatics notes: du/Sie, register, politeness. They share
-- the grammar table and the teach flow; the category is what gives them
-- their own slot on the trainer's agenda.

insert into public.grammar_patterns (key, name, explanation, examples, cefr, mini_level, difficulty, common_mistakes, related_pattern_keys, category)
values
  ('du_oder_sie', 'Choice between du and Sie',
   'Sie with the surname is the default for adults you do not know — shops, offices, strangers on the street. du is for friends, family, children and fellow students. Getting this wrong is not a grammar mistake: du to a stranger reads as disrespect, Sie to a close friend as distance.',
   array['Entschuldigung, können Sie mir helfen?', 'Kommst du heute Abend mit?', 'Wie heißen Sie, bitte?']::text[],
   'A1', 1, 1,
   array['*Wie heißt du? — to an official at a counter → Wie heißen Sie? Strangers and officials get Sie.', '*Können Sie mir das Salz geben, Papa? → Kannst du mir das Salz geben? Family is du.']::text[],
   array['personal_pronouns_nominative']::text[],
   'culture'),
  ('bitte_und_danke', 'Three jobs of bitte',
   'bitte does three jobs: please when you ask, here you are when you hand something over, and you are welcome after Danke. One more trap: a bare Danke in answer to an offer means no, thanks — accept with Ja, bitte or Gern.',
   array['Einen Kaffee, bitte.', 'Bitte schön! — Danke! — Bitte!', 'Noch etwas Wasser? — Ja, bitte!']::text[],
   'A1', 8, 1,
   array['*Noch Kaffee? — Danke! — when you wanted more → Ja, bitte. A bare Danke declines the offer.', '*Hier bitte, danke → Bitte schön. Handing something over takes bitte, not danke.']::text[],
   array['moechten_present']::text[],
   'culture'),
  ('fremde_ansprechen', 'Polite way to address strangers',
   'Open with Entschuldigung and stay with Sie and the formal imperative when you stop a stranger — for directions, in a shop, on the platform. Hallo du or a bare imperative to someone you do not know reads as pushy rather than friendly.',
   array['Entschuldigung, wo ist der Bahnhof?', 'Entschuldigen Sie, ist hier noch frei?', 'Sagen Sie mal, hält hier der Bus?']::text[],
   'A1', 11, 1,
   array['*Hey, wo ist der Bahnhof? → Entschuldigung, wo ist der Bahnhof? Strangers are approached with an apology, not a hey.', '*Sag mal, wo ist die Haltestelle? — to a stranger → Sagen Sie mal. The formal imperative belongs with Sie.']::text[],
   array['imperative_formal', 'du_oder_sie']::text[],
   'culture'),
  ('wie_gehts_unter_freunden', 'Wie geht es dir as a real question',
   'Unlike the English how are you, Wie geht es dir is asked of people you know and expects a real answer — Germans do not use it as a passing greeting with strangers or shop staff. Asked seriously, it may also get a serious answer, including a genuinely bad one.',
   array['Wie geht es dir? — Ehrlich gesagt, nicht so gut.', 'Na, wie geht es? — Ganz gut, und dir?', 'Guten Tag! — as the whole greeting to a stranger']::text[],
   'A1', 15, 2,
   array['*Wie geht es Ihnen? — to a cashier, in passing → Guten Tag. The question invites a conversation you are not starting.', '*Gut, danke! — every single time → Muss, or Ganz okay, when it is true; a real question deserves a real answer.']::text[],
   array['du_oder_sie']::text[],
   'culture'),
  ('puenktlichkeit_und_absagen', 'Punctuality and cancelling politely',
   'Being on time is read as respect: for a private invitation, arrive within a few minutes of the agreed time, and for anything official, slightly early. If you cannot make it, cancel as soon as you know — with a reason and an apology. A silent no-show, or a cancellation an hour before, costs trust.',
   array['Ich schaffe es leider nicht, tut mir wirklich leid.', 'Können wir auf nächste Woche verschieben?', 'Ich komme fünf Minuten später — Entschuldigung!']::text[],
   'A2', 16, 2,
   array['*Einfach nicht hingehen und nichts sagen → Ich muss leider absagen. A no-show without a word reads as disrespect.', '*Ich komme vielleicht — as an accepted invitation → Ich komme, or Ich kann leider nicht. A firm yes or a clear no.']::text[],
   array['modal_verb_wollen']::text[],
   'culture'),
  ('schriftliche_anrede', 'Formal salutations in writing',
   'Formal letters and mails open with Sehr geehrte Frau X or Sehr geehrter Herr Y and close with Mit freundlichen Grüßen. In the text, the formal Sie, Ihnen and Ihr keep their capital letter. Liebe and Viele Grüße belong to people you already know.',
   array['Sehr geehrte Frau Weber, ...', 'Mit freundlichen Grüßen, Raj Kumar', 'Vielen Dank für Ihre Antwort.']::text[],
   'A2', 24, 2,
   array['*Hallo Herr Weber — in a job application → Sehr geehrter Herr Weber. Applications keep the full formal register.', '*vielen Dank für ihre Antwort → für Ihre Antwort. The formal Ihr is capitalised everywhere in the sentence.']::text[],
   array['formal_register_sie']::text[],
   'culture'),
  ('reklamieren_mit_stil', 'Firm but polite complaint',
   'Complaining is normal and direct in Germany: name the problem plainly, say what you want done, and stay formal. The softness comes from Konjunktiv II — Ich hätte gern, Könnten Sie — not from apologising for complaining at all.',
   array['Die Jacke ist kaputt. Ich möchte sie umtauschen.', 'Ich hätte gern mein Geld zurück.', 'Könnten Sie das bitte prüfen?']::text[],
   'A2', 27, 2,
   array['*Entschuldigung, es tut mir leid, aber vielleicht ist die Jacke eventuell kaputt? → Die Jacke ist kaputt. Name the problem; the politeness sits in the request, not in apology stacking.', '*Das ist Betrug! — for a broken zip → Ich möchte die Jacke reklamieren. Direct, not dramatic.']::text[],
   array['modal_verb_duerfen', 'bitten_abschwaechen']::text[],
   'culture'),
  ('duzen_anbieten', 'Offer of the du',
   'The switch from Sie to du is offered, not taken — and by the older or more senior person. A common form is: Wir können uns duzen. Ich bin Anna. Accept with your own first name. Once agreed, the du is permanent; switching back would be an insult.',
   array['Wir können uns duzen. Ich bin Anna.', 'Gern! Ich bin Raj.', 'Sollen wir beim Du bleiben?']::text[],
   'A2', 30, 3,
   array['*Du, Frau Weber, hast recht — uninvited, to a senior colleague → Sie haben recht, until she offers the du.', '*Sie sind sehr nett, Anna! — after agreeing on du → Du bist sehr nett. The du, once offered, stays.']::text[],
   array['du_oder_sie', 'sie_und_du_im_beruf']::text[],
   'culture'),
  ('smalltalk_themen', 'Small-talk topics and taboos',
   'Safe small-talk ground: weather, travel, food, the region, how the journey was. Salary, rent, weight, and probing personal questions come across as intrusive early on. And a pause in the conversation is not hostility — German small talk tolerates silence better than English does.',
   array['Ganz schön kalt heute, oder?', 'Waren Sie schon mal in Dresden?', 'Wie war die Anreise?']::text[],
   'A2', 35, 3,
   array['*Was verdienst du eigentlich? — at a first meeting → Was machst du beruflich? The job is fine; the number is not.', '*Nervously filling every pause → Eine kurze Stille ist okay. Silence is not an emergency.']::text[],
   array['w_questions']::text[],
   'culture'),
  ('bitten_abschwaechen', 'Softening a request',
   'German softens a request with Konjunktiv II plus small words — mal, kurz, vielleicht, eventuell — rather than by repeating bitte. Könnten Sie mir kurz helfen? is softer than Bitte bitte helfen Sie mir, and sounds like a native speaker rather than a plea.',
   array['Könnten Sie mir kurz helfen?', 'Würdest du mal das Fenster aufmachen?', 'Hätten Sie vielleicht einen Moment Zeit?']::text[],
   'B1', 42, 3,
   array['*Helfen Sie mir, bitte, bitte! → Könnten Sie mir vielleicht helfen? Softness comes from the Konjunktiv and the particles, not from stacking bitte.', '*Ich will, dass Sie mir helfen → Ich hätte eine Bitte an Sie. A bare ich will reads as a demand.']::text[],
   array['konjunktiv_ii_politeness']::text[],
   'culture'),
  ('sie_und_du_im_beruf', 'Formality at work',
   'Sie plus the surname is the workplace default, even between people who have shared an office for years. Some teams — start-ups especially — agree on du for everyone. Follow the local convention and the lead of senior colleagues, not your instinct from English-speaking workplaces.',
   array['Frau Weber, hätten Sie kurz Zeit?', 'Bei uns duzen sich alle — auch der Chef.', 'Herr Schmidt, was halten Sie davon?']::text[],
   'B1', 46, 4,
   array['*Du, Chef, hast du kurz Zeit? — in a Sie workplace → Hätten Sie kurz Zeit? The office convention outranks friendliness.', '*Frau Weber, Sie... — in a team that agreed on du → Anna, du... Refusing the agreed du also lands wrong.']::text[],
   array['duzen_anbieten', 'formal_register_sie']::text[],
   'culture'),
  ('vorstellungsgespraech_umgangsformen', 'Interview conventions',
   'In a job interview the register is part of what is assessed: Sie throughout, Herr or Frau plus surname, titles where they exist, a firm greeting, and arrive early rather than on the dot. Wait for the interviewer to offer a seat, and never slide into du even if the mood is warm.',
   array['Guten Tag, Frau Dr. Weber. Danke für die Einladung.', 'Gern beantworte ich Ihre Frage.', 'Ich freue mich auf Ihre Rückmeldung.']::text[],
   'B1', 47, 4,
   array['*Hi! Ich bin der Raj. — as an interview opening → Guten Tag, mein Name ist Raj Kumar. First names alone are for later.', '*Punkt zehn Uhr eintreffen → zehn Minuten früher da sein. On the dot already counts as knapp.']::text[],
   array['schriftliche_anrede', 'sie_und_du_im_beruf']::text[],
   'culture'),
  ('amtssprache', 'Register at the Behörde',
   'At the Behörde everything runs on Sie, Termine and paper: address officials formally, bring every document, and expect the language of forms — der Antrag, die Bescheinigung, zuständig. Matching the register and having the papers ready lowers the friction more than charm does.',
   array['Ich habe einen Termin um zehn Uhr.', 'Welche Unterlagen brauchen Sie von mir?', 'Ist diese Stelle für die Anmeldung zuständig?']::text[],
   'B1', 50, 4,
   array['*Kannst du mir das Formular geben? — at the counter → Könnten Sie mir das Formular geben? Officials get Sie, always.', '*Einfach ohne Termin vorbeigehen → vorher einen Termin vereinbaren. The Termin is the door.']::text[],
   array['fremde_ansprechen', 'nominalisation']::text[],
   'culture'),
  ('direktheit_verstehen', 'Directness without rudeness',
   'German feedback is sachlich: about the thing, not the person. Das stimmt nicht is a normal sentence in a meeting, not an attack — and blunt disagreement usually signals engagement, not hostility. Read directness as information; answer it in kind, calmly and with reasons.',
   array['Das sehe ich anders, weil ...', 'Der Plan hat ein Problem: der Termin ist zu knapp.', 'Da haben Sie recht, das war mein Fehler.']::text[],
   'B1', 61, 5,
   array['*Taking Das stimmt nicht as a personal insult → Es geht um die Sache. Disagreement with the point is not disrespect for the person.', '*Ich bin nicht sicher, aber vielleicht, eventuell ... — to soften real criticism → Ich sehe ein Problem. Sagen, was Sache ist.']::text[],
   array['smalltalk_themen']::text[],
   'culture'),
  ('regionale_gruesse', 'Regional greetings',
   'Hallo works everywhere, but the regions greet in their own words: Moin in the north — at any hour, not just mornings — Grüß Gott and Servus in the south and in Austria, Grüezi over the Swiss border. Using the local greeting reads as friendly; correcting someone''s Moin at 3 pm reads as not knowing it.',
   array['Moin! — in Hamburg, auch nachmittags', 'Grüß Gott! — in München', 'Servus, bis später!']::text[],
   'B1', 65, 5,
   array['*Moin heißt guten Morgen → Moin gilt den ganzen Tag. It is a greeting, not a time of day.', '*Grüß Gott — in Hamburg → Moin. The southern greeting travels badly north.']::text[],
   array['du_oder_sie']::text[],
   'culture')
on conflict (key) do update set
  name = excluded.name,
  explanation = excluded.explanation,
  examples = excluded.examples,
  cefr = excluded.cefr,
  mini_level = excluded.mini_level,
  difficulty = excluded.difficulty,
  common_mistakes = excluded.common_mistakes,
  related_pattern_keys = excluded.related_pattern_keys,
  category = excluded.category;
